select tpa.test_project_api_id as testProjectApiId, tpa.test_project_id as testProjectId, tpa.api_group_id as apiGroupId, tpa.api_status as apiStatus, tpa.api_group as apiGroup, tpa.api_name as apiName, tpa.api_description as apiDescription, tpa.api_path as apiPath, tpa.protocol_type as protocolType, tpa.request_config as requestConfig, tpa.headers as headers, tpa.cookies as cookies, tpa.response_config as responseConfig, tpa.test_value_config as testValueConfig, tpa.biz_code_config as bizCodeConfig, tpa.design_hints as designHints, tpa.auth_config as authConfig, tpa.pre_request_script as preRequestScript, tpa.post_request_script as postRequestScript, tpa.last_sync_time as lastSyncTime, tpa.del_status as delStatus, tpa.create_time as createTime, tpa.update_time as updateTime from test_project_api tpa where tpa.del_status = 0
and tpa.test_project_id = #{testProjectId}
and tpa.api_group_id = #{apiGroupId}
